/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import ghilbert = require( './index' );


// TESTS //

// The function returns a collection...
{
	const out = new Float64Array( 9 );

	ghilbert( 'row-major', 3, out, 3 ); // $ExpectType Float64Array
	ghilbert( 'row-major', 3, new AccessorArray( out ), 3 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const out = new Float64Array( 9 );

	ghilbert( 10, 3, out, 3 ); // $ExpectError
	ghilbert( true, 3, out, 3 ); // $ExpectError
	ghilbert( false, 3, out, 3 ); // $ExpectError
	ghilbert( null, 3, out, 3 ); // $ExpectError
	ghilbert( undefined, 3, out, 3 ); // $ExpectError
	ghilbert( [], 3, out, 3 ); // $ExpectError
	ghilbert( {}, 3, out, 3 ); // $ExpectError
	ghilbert( ( x: number ): number => x, 3, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert( 'row-major', '10', out, 3 ); // $ExpectError
	ghilbert( 'row-major', true, out, 3 ); // $ExpectError
	ghilbert( 'row-major', false, out, 3 ); // $ExpectError
	ghilbert( 'row-major', null, out, 3 ); // $ExpectError
	ghilbert( 'row-major', undefined, out, 3 ); // $ExpectError
	ghilbert( 'row-major', [], out, 3 ); // $ExpectError
	ghilbert( 'row-major', {}, out, 3 ); // $ExpectError
	ghilbert( 'row-major', ( x: number ): number => x, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a collection...
{
	ghilbert( 'row-major', 3, 10, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, true, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, false, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, null, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, undefined, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, {}, 3 ); // $ExpectError
	ghilbert( 'row-major', 3, ( x: number ): number => x, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert( 'row-major', 3, out, '10' ); // $ExpectError
	ghilbert( 'row-major', 3, out, true ); // $ExpectError
	ghilbert( 'row-major', 3, out, false ); // $ExpectError
	ghilbert( 'row-major', 3, out, null ); // $ExpectError
	ghilbert( 'row-major', 3, out, undefined ); // $ExpectError
	ghilbert( 'row-major', 3, out, [] ); // $ExpectError
	ghilbert( 'row-major', 3, out, {} ); // $ExpectError
	ghilbert( 'row-major', 3, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const out = new Float64Array( 9 );

	ghilbert(); // $ExpectError
	ghilbert( 'row-major' ); // $ExpectError
	ghilbert( 'row-major', 3 ); // $ExpectError
	ghilbert( 'row-major', 3, out ); // $ExpectError
	ghilbert( 'row-major', 3, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray( 3, out, 3, 1, 0 ); // $ExpectType Float64Array
	ghilbert.ndarray( 3, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray( '10', out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( true, out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( false, out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( null, out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( undefined, out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( [], out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( {}, out, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( ( x: number ): number => x, out, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a collection...
{
	ghilbert.ndarray( 3, 10, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, true, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, false, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, null, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, undefined, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, {}, 3, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, ( x: number ): number => x, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray( 3, out, '10', 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, true, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, false, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, null, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, undefined, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, [], 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, {}, 1, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray( 3, out, 3, '10', 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, true, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, false, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, null, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, undefined, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, [], 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, {}, 0 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray( 3, out, 3, 1, '10' ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, true ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, false ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, null ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, undefined ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, [] ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, {} ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const out = new Float64Array( 9 );

	ghilbert.ndarray(); // $ExpectError
	ghilbert.ndarray( 3 ); // $ExpectError
	ghilbert.ndarray( 3, out ); // $ExpectError
	ghilbert.ndarray( 3, out, 3 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1 ); // $ExpectError
	ghilbert.ndarray( 3, out, 3, 1, 0, 10 ); // $ExpectError
}
